package com.networkmonitorpro.ui; import android.content.*;import android.graphics.*;import android.util.*;import android.view.*;import java.util.*; public class SpeedGraphView extends View{ private final Paint p=new Paint(1); private final ArrayDeque<Float> vals=new ArrayDeque<>(); public SpeedGraphView(Context c,AttributeSet a){super(c,a); p.setStrokeWidth(4); p.setStyle(Paint.Style.STROKE);} public void add(long bps){if(vals.size()>60)vals.removeFirst(); vals.addLast((float)Math.min(100,bps/1000000f)); invalidate();} protected void onDraw(Canvas c){super.onDraw(c); p.setColor(Color.rgb(0,200,83)); Path path=new Path(); int i=0,n=Math.max(1,vals.size()-1); for(float v:vals){float x=i++*getWidth()/Math.max(1,n), y=getHeight()-(v/100f)*getHeight(); if(i==1)path.moveTo(x,y); else path.lineTo(x,y);} c.drawPath(path,p);} }
